INSERT INTO changelog (title, body, created_at) VALUES ('Великі витяжки більше не ламаються', 'Витяжки з Claude Code (продукт, оновлення, стратегія) тепер розбираються з великим запасом довжини — раніше велика витяжка обрізалась посередині і падала з помилкою. Розбір може тривати до 1–2 хв. Якщо витяжка зовсім величезна — система прямо скаже «розбий на 2 частини».', datetime('now'));
